import{_ as e,o as a,c as n,a2 as o}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Channels","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/index.md","filePath":"integrations/channels/index.md","lastUpdated":1781609185000}'),r={name:"integrations/channels/index.md"};function i(s,t,d,l,h,c){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h1><p>Channels connect Memoh bots to messaging platforms. Configure them from the bot <strong>Platforms</strong> tab so users can talk to the same bot through Slack, Telegram, Feishu, Discord, WeChat, Email, the web UI, and other surfaces.</p><h2 id="supported-channels" tabindex="-1">Supported Channels <a class="header-anchor" href="#supported-channels" aria-label="Permalink to &quot;Supported Channels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Guide</th><th>Notes</th></tr></thead><tbody><tr><td>Slack</td><td><a href="/integrations/channels/slack.html">Slack Configuration</a></td><td>Workspace messaging with threads</td></tr><tr><td>Telegram</td><td><a href="/integrations/channels/telegram.html">Telegram Configuration</a></td><td>Strong attachment and streaming support</td></tr><tr><td>Feishu (Lark)</td><td><a href="/integrations/channels/feishu.html">Feishu Configuration</a></td><td>Supports webhook-style inbound mode</td></tr><tr><td>Discord</td><td><a href="/integrations/channels/discord.html">Discord Configuration</a></td><td>Good fit for communities and servers</td></tr><tr><td>QQ</td><td><a href="/integrations/channels/qq.html">QQ Configuration</a></td><td>Personal DM oriented</td></tr><tr><td>Matrix</td><td><a href="/integrations/channels/matrix.html">Matrix Configuration</a></td><td>Decentralized homeserver support</td></tr><tr><td>Misskey</td><td><a href="/integrations/channels/misskey.html">Misskey Configuration</a></td><td>Replies and reactions, no streaming</td></tr><tr><td>DingTalk</td><td><a href="/integrations/channels/dingtalk.html">DingTalk Configuration</a></td><td>Enterprise private/group chat</td></tr><tr><td>WeCom (WeWork)</td><td><a href="/integrations/channels/wecom.html">WeCom Configuration</a></td><td>Enterprise workspace integration</td></tr><tr><td>WeChat</td><td><a href="/integrations/channels/weixin.html">WeChat Configuration</a></td><td>Personal QR login flow</td></tr><tr><td>WeChat Official Account</td><td><a href="/integrations/channels/wechatoa.html">WeChat Official Account Configuration</a></td><td>Official account webhook flow</td></tr><tr><td>Email</td><td><a href="/guides/email.html">Email</a></td><td>SMTP, Mailgun, Gmail OAuth, and related email provider flows</td></tr><tr><td>Web</td><td>Built-in</td><td>Available from the Memoh web interface</td></tr></tbody></table><h2 id="wechat-options" tabindex="-1">WeChat Options <a class="header-anchor" href="#wechat-options" aria-label="Permalink to &quot;WeChat Options&quot;">​</a></h2><p>Memoh supports two different WeChat-related adapters:</p><ul><li><strong>WeChat (<code>weixin</code>)</strong> is the personal-account style integration that relies on QR login.</li><li><strong>WeChat Official Account (<code>wechatoa</code>)</strong> is the official-account webhook integration that uses <code>App ID</code>, <code>App Secret</code>, <code>Token</code>, and optional AES settings.</li></ul><p>Choose the one that matches your actual WeChat deployment model.</p><h2 id="general-setup-flow" tabindex="-1">General Setup Flow <a class="header-anchor" href="#general-setup-flow" aria-label="Permalink to &quot;General Setup Flow&quot;">​</a></h2><ol><li>Register an app or bot on the target platform.</li><li>Obtain credentials such as API tokens, app IDs, app secrets, or access tokens.</li><li>Add the channel from the bot <strong>Platforms</strong> tab in Memoh.</li><li>Save and enable the channel.</li></ol><p>Depending on the platform, the final step may involve copying a webhook callback URL into the platform console, approving a QR login on mobile, or keeping a stream/WebSocket connection running through Memoh.</p>',11)])])}const g=e(r,[["render",i]]);export{m as __pageData,g as default};
